namespace camel::core::error {

enum class SemanticDiag : uint32_t {
    // Errors
    // 0x0001E5 vacant
    Redeclaration               = 0x000001,
    ModuleNotFound              = 0x000002,
    ReservedIdentifier          = 0x000003,
    TupleUnpackingCountMismatch = 0x000004,
    InvalidLiteral              = 0x000005,
    DuplicateDictKey            = 0x000006,
    DuplicateParameter          = 0x000009,
    UnresolvedTypeReference     = 0x00000A,
    UnresolvedReference         = 0x00000B,
    BranchReturnTypeMismatch    = 0x00000C,
    InvalidAccessIndex          = 0x00000D,
    TypeNotIndexable            = 0x00000E,
    NoMatchingFunction          = 0x00000F,
    ArgumentsMismatch           = 0x000010,
    ReturnTypeMismatch          = 0x000011,
    ElementTypeMismatch         = 0x000012,
    CallingIncompleteFunction   = 0x000013,
    // 0x000014: empty. The number is not reused.
    ImportNameNotExported = 0x000015,
    // A literal the type it is given cannot hold: out of range, truncated (a decimal literal
    // in an integer type), or not a value of that type at all (a text that is not a number).
    // One diagnostic for all of them: it says which literal, which type, and
    // why.
    LiteralNotRepresentable     = 0x000016,
    DynamicCastForbidden        = 0x000017,
    ModuleParseFailed           = 0x000018,
    InvalidOperatorURI          = 0x000019,
    EntryModuleMissingMain      = 0x00001B,
    ArgumentsRejected           = 0x00001C,
    ImmutablePassedToVarParam   = 0x00001D,
    AssignmentTargetNotVariable = 0x00001E,
    ConstructNotSupported       = 0x00001F,
    InvalidTypeArgument         = 0x000020,
    ArgumentNeedsConversion     = 0x000021,
    ReturnNeedsConversion       = 0x000022,
    // 0x000023: empty. The number is not reused.
    // 0x000025: empty. The number is not reused.
    // 0x000026: empty. The number is not reused.
    ImportNameConflict = 0x000027,
    // An error: the construct it reports is not compiled, so a program that uses it must not
    // run. It used to be a warning (0x100000), and the declaration that used the feature was
    // dropped while the rest of the program went on.
    FeatureNotSupported = 0x000040,
    // Generic functions and type functions (design principles 5.6).
    TypeVariableRedeclared      = 0x000051,
    TypeVariableNotBindable     = 0x000052,
    GenericArgumentsMismatch    = 0x000053,
    GenericFunctionAsValue      = 0x000054,
    GenericInstantiationTooDeep = 0x000055,
    TypeFunctionArguments       = 0x000056,
    GenericFunctionUnsupported  = 0x000057,
    // Functions as values.
    FunctionNameAsValue = 0x000060,
    // Nullable and fallible values (design principles 3.8;
    // docs/technical/29_nullable_and_fallible_values.md).
    // 0x000074: empty. The number is not reused.
    ThrowOutsideFallible  = 0x000070,
    ThrowNotAnError       = 0x000071,
    TaggedTypeNesting     = 0x000072,
    TaggedValueNotOpened  = 0x000073,
    TaggedOperandMismatch = 0x000075,
    TaggedMatchCases      = 0x000076,
    // Reporting several errors (0x80 and up, clear of the blocks above).
    ImportedModuleHasErrors = 0x000080,
    // Map and Set (design principles 11.3; docs/technical/31_map_and_set.md).
    CollectionKeyNotAllowed = 0x0000A0,
    DuplicateCollectionKey  = 0x0000A1,
    // Design principles log 2.10: 0xB0 and up.
    MatchWithoutDefault        = 0x0000B0,
    IfWithoutElseAsValue       = 0x0000B1,
    EmptyArrayWithoutType      = 0x0000B2,
    PartialApplicationRefused  = 0x0000B3,
    ComprehensionSourceRefused = 0x0000B4,
    // Design principles log 2.11: 0xC0 and up.
    LogicalOperandNotBool = 0x0000C0,
    // Modules and namespaces (design principles 10.1, 10.2): 0xD0 and up.
    ExportedVariable          = 0x0000D0,
    ModuleValueCycle          = 0x0000D1,
    CaptureAfterRecursiveCall = 0x0000D2,
    AmbiguousName             = 0x0000D3,
    // 0xE0-0xE2: empty. The numbers are not reused.
    // The condition and the cases of a branch.
    ConditionNotBool      = 0x0000E3,
    MatchCaseTypeMismatch = 0x0000E4,
    // Rules (design principles log 2.12) on operators and on collections that
    // are not changed in place: 0xF0 and up.
    UnusedPureResult         = 0x0000F0,
    OperatorNotOverloadable  = 0x0000F1,
    OperatorOverloadInvalid  = 0x0000F2,
    OperatorOverloadConflict = 0x0000F3,
    // A call (of a function, an operator or a partial application used as a value) that
    // more than one overload takes: several candidates in the pass being used, never
    // settled by declaration order (design principles 5.1). Renamed from
    // AmbiguousOperatorCall when it became the report for every call; the code is unchanged.
    AmbiguousCall = 0x0000F4,
    // Design principles log 2.13 and the defects found with it: 0x110
    // and up.
    DeclaredTypeMismatch = 0x000110,
    ModuleTypeCycle      = 0x000111,
    InvalidAnnotation    = 0x000112,
    // The structured loop (design principles 3.10): 0x120 and up.
    LoopBodyTypeMismatch    = 0x000121,
    LoopStateWithoutType    = 0x000122,
    LoopConditionNotBool    = 0x000123,
    LoopNameRepeated        = 0x000124,
    LoopSequenceNotIterable = 0x000120,
    // Design principles log 2.13: the nominal enum, 0x130 and up.
    DuplicateEnumVariant   = 0x000130,
    DuplicateEnumField     = 0x000131,
    EnumVariantFieldCount  = 0x000133,
    EnumPatternMismatch    = 0x000134,
    EnumMatchNotExhaustive = 0x000135,
    EnumFieldAccess        = 0x000136,
    // 0x137-0x138: empty. The numbers are not reused.
    EnumTypeArgumentNotInferred = 0x000139,
    /// A type variable that a call's arguments leave without a type, because the only argument that
    /// mentions it is an empty literal, which states no element type.
    FunctionTypeArgumentNotInferred = 0x0001F6,
    EnumFieldTypeMismatch           = 0x00013A,
    EnumConstructionMismatch        = 0x00013B,
    // Named dimensions of type extents (design principles 5.4): 0x140 and up.
    ConstasNotAllowed         = 0x000140,
    DimensionNameNotBound     = 0x000141,
    DimensionNameAlreadyBound = 0x000142,
    DimensionMismatch         = 0x000143,
    InvalidExtentExpression   = 0x000144,
    // Automatic differentiation (design principles 9.9): 0x150 and up.
    NotDifferentiable = 0x000150,
    // Tags (design principles 6.2): 0x160 and up.
    TagNotAtPosition       = 0x000161,
    TagUndeclared          = 0x000162,
    TagArgumentCount       = 0x000163,
    TagArgumentNotConstant = 0x000164,
    TagOnUnnamedField      = 0x000167,
    TagArgumentNamed       = 0x000168,
    TagArgumentType        = 0x00016A,
    TagNotAPermission      = 0x00016B,
    RuleTagNotRequires     = 0x00016C,
    TagParameterType       = 0x00016D,
    TagShadowsPermission   = 0x00016E,
    /// Two tags of one field are written with the same name.
    TagFieldNameAmbiguous = 0x0001EA,
    /// A tag argument is a function, which a `static` head has no value for.
    TagFunctionArgumentNotReadable = 0x0001EB,
    // Static expansion (design principles 5.5): 0x170 and up.
    StaticMatchNotExhaustive   = 0x000170,
    StaticMatchUnreachableCase = 0x000171,
    StaticTypeNotConcrete      = 0x000172,
    StaticMatchTooDeep         = 0x000173,
    GenericInstantiationCycle  = 0x000174,
    // A recursive generic call whose type argument is built out of the type the caller already
    // instantiated (design principles 5.5): 'f::<T>(x: T)' calling 'f([x])' asks for one instance
    // per level, and no level's key ever repeats. The count of open instances is not what bounds
    // this, so the call is refused where the growth first appears.
    GenericTypeArgumentGrows       = 0x0001EC,
    StaticForNotComposite          = 0x000175,
    StaticAccessNotInternal        = 0x000176,
    StaticAccessUnknownField       = 0x000177,
    StaticAccessIndexOutOfRange    = 0x000178,
    StaticAccessNotConstant        = 0x000179,
    StaticComprehensionVoidElement = 0x00017A,

    // `indices`. 0x17B-0x17D are the body-less declaration diagnostics below, so
    // this one takes the next free code after them.
    StaticIndicesNotTuple = 0x000182,

    // The sequence of a `static loop` (and):
    // the head lost the parentheses it carried and takes any sequence known when the function is
    // compiled. One rule draws the line -- compile-time constants joined by operations that are
    // pure and cannot fail -- so what counts is the interval, `range`, an array and a compile-time
    // tuple, not a list of spellings. One the compiler cannot work out is this.
    StaticLoopSequenceNotKnown = 0x0001E7,

    // The names of a `static for` / `static loop` head (the rule on
    // `static-loop-sequence-two-argument-range-and-the-tuple-reading`, item 4): the number of names
    // follows the element -- `fields T` gives the field's name, its type and its tags, every other
    // element gives one thing -- and a head that names more than the element has parts is this.
    StaticHeadNameCount = 0x000000,

    // Rest parameters (design principles 5.5, step 6): 0x18A and up.
    /// A rest parameter is not the last of the ordinary parameters.
    RestParameterNotLast = 0x00018A,
    /// A type was written after `..`: a rest parameter is untyped.
    RestParameterTypeNotSupported = 0x00018B,
    /// A `..e` argument is followed by another argument.
    RestArgumentNotLast = 0x00018D,
    /// The operand of `..e` is not a compile-time tuple.
    RestArgumentNotTuple = 0x00018E,
    /// A rest function was used where a function value is needed.
    RestFunctionNeedsExpansion = 0x00018F,
    /// A call passes fewer arguments than the fixed parameters of a rest function.
    RestArgumentsMismatch = 0x000190,
    /// A rest parameter's build-time tuple was used where a runtime value is needed.
    StaticTupleEscapes = 0x00019C,

    // `constas` value parameters (design principles 5.4): 0x191 and up. 0x18C stays free.
    /// A `constas` parameter writes no type.
    ConstasTypeRequired = 0x000193,
    /// The argument bound to a `constas` parameter is not a compile-time constant.
    ConstasValueNotConstant = 0x000195,
    /// A `constas` declaration was used where a function value is needed.
    ConstasFunctionNeedsCall = 0x000199,
    /// A `constas` declaration is a body-less declaration of a C++ operator.
    ConstasInNativeDeclaration = 0x00019A,
    /// A call to a `constas` declaration gives no value for the parameter.
    ConstasArgumentMissing = 0x00019B,
    /// A tag gives a fact one value where the node already has another.
    TagValueConflict = 0x00019D,
    /// A dimension pack (`..rest`) is not the last item of its `[...]`, or is written twice.
    DimensionAfterAnyRank = 0x00019E,

    // The resource surface of a program (docs/design/effects/plan.cn.md step 3): the `resource`
    // declaration, `uses`/`pure` and the `#resource` tag. 0x1A0 and up.
    /// A name in a `uses` clause is neither a parameter nor a declared resource.
    UnknownResource = 0x0001A0,
    /// A signature says both `pure` and `uses`.
    PureAndUses = 0x0001A1,
    /// A resource group names itself, directly or through other groups.
    ResourceGroupCycle = 0x0001A2,
    /// `#resource` is written before a type declaration that is not nominal.
    HandleTypeNotNominal = 0x0001A3,
    /// A body-less declaration's clause differs from the operator's declared resources.
    NativeResourceMismatch = 0x0001A4,

    // `std::cml`, the source printer (step S1). 0x1A5 and up.
    /// A graph holds a construct the printer does not turn into source.
    CmlUnsupportedConstruct = 0x0001A5,
    /// A constant is larger than the printer's max_literal_bytes.
    CmlBigConstant = 0x0001A6,

    // Array element types (design/arrays-memory, P4 "element type exact"). 0x1A7: empty. The
    // number is not reused.

    // Applicability conditions (`when`, design principles 4.4). 0x1A8 and up.
    /// The condition's value is not a bool.
    WhenConditionNotBool = 0x0001A8,
    /// The condition is not a compile-time predicate the compiler can evaluate.
    WhenConditionNotConstant = 0x0001A9,
    /// The condition names something outside the declaration.
    WhenUnknownName = 0x0001AA,
    /// A type query is asked about a type that is still open (a type variable).
    WhenTypeQueryNotConcrete = 0x0001AB,
    /// No candidate of a call applies: every condition that could take it is false.
    WhenConditionUnmet    = 0x0001AC,
    EffectInRuleCondition = 0x0001AD,

    // Defaults of `with` parameters and `with` arguments given by name (design principles 4.4).
    // 0x1B7 to 0x1BE; 0x1BF and up belong to `when` predicate lookup.
    /// A named `with` argument does not name a `with` parameter of the callee.
    WithArgumentUnknown = 0x0001B7,
    /// A `with` parameter is given twice, once by position and once by name.
    WithArgumentDuplicate = 0x0001B8,
    /// A call gives no value for a `with` parameter that has no default.
    WithArgumentMissing = 0x0001B9,
    /// The default of a `with` parameter is not a compile-time constant.
    WithDefaultNotConstant = 0x0001BA,
    /// The default of a `with` parameter has a type that does not fit the parameter.
    WithDefaultWrongType = 0x0001BB,
    /// A `with` parameter without a default follows one that has a default.
    WithParameterAfterDefault = 0x0001BC,
    /// A `with` argument is given by name where the callee's signature is not known.
    WithArgumentCallee = 0x0001BD,
    /// A `with` argument is given by name in a binding used as a function value.
    WithArgumentInValue = 0x0001BE,

    // Predicate lookup in a `when` condition (design principles 4.4, 10.2). 0x1BF and up.
    /// A predicate another module declares, but this module does not import it.
    WhenPredicateNotImported = 0x0001BF,
    /// A name an import brings exists, but it is not a generic function answered at compile time.
    WhenPredicateNotCompileTime = 0x0001C0,
    /// Two imports bring a predicate of the same name, and neither is chosen.
    WhenPredicateAmbiguous = 0x0001C1,

    // Body-less declarations, the declarations of a C++ module's operators (design principles
    //  6.4, step 1). 0x17B and up.
    NativeDeclarationIncomplete = 0x00017B,
    NativeDeclarationNotLoaded  = 0x00017C,
    // Body-less declarations: 0x17E and up.
    /// Two generic declarations of one name can take the same call (rule 2).
    NativeDeclarationOverlap = 0x000180,
    // Same-named `#impl` declarations split by their conditions (design principles 4.4): two
    // same-named declarations whose `when` conditions are mutually exclusive are overloads and may
    // stand side by side; a type that satisfies both is this overlap. The conditions are asked about
    // every type the compiler registers, and a condition it cannot answer leaves the pair refused by
    // the older code above.
    WhenDeclarationOverlap = 0x0001E0,
    /// A declaration names an operator of another module (rule 5).
    NativeDeclarationForeignOperator = 0x000181,

    // A lambda's parameter that writes no type and that the function type of its position does
    // not determine (design principles 5.9). 0x17E and up.
    LambdaParameterWithoutType = 0x00017E,

    // `typeof` and the same-shape comprehension (design principles 5.6, generic-structure
    // README R3). 0x1B3 and up.
    /// The expression after `typeof` has no value, so the type it stands for cannot be taken.
    TypeOfNotAValue = 0x0001B3,
    /// `typeof` is written inside a larger type (`typeof e[]`, `(typeof e, int)`).
    TypeOfNotWholeType = 0x0001B4,
    /// `T { static for ... }` names a type that is not a struct or a tuple.
    SameShapeComprehensionNotComposite = 0x0001B5,
    /// `T { static for n, F in fields U }` walks a type other than the shape `T`.
    SameShapeComprehensionMismatch = 0x0001B6,

    // Type identity in `match type` (`case int`, `case T`; design principles 5.5). 0x1C2.
    /// An identity pattern names a type that cannot select the subject: `void`, a `typeof`
    /// expression, an open type variable, a type written twice in one case, or a type that an
    /// earlier case already selects.
    StaticMatchPatternCannotMatch = 0x0001C2,
    FactArgumentNotConstant       = 0x0001C3,
    FactCaseDefaultMissing        = 0x0001C4,
    // Folding a call of a pure function with constant arguments. 0x1C5 and up.
    /// An argument of a call in a place that needs a constant is not one.
    FoldCallArgumentNotConstant = 0x0001C5,
    /// The call has effects: it is `sync`, writes a `var`, or uses a resource.
    FoldCallHasEffects = 0x0001C6,
    /// The call nests deeper than the evaluator follows: it recurses without a base case here.
    FoldCallTooDeep = 0x0001C7,
    /// The call's result is not a kind a constant can have.
    FoldCallResultNotConstant = 0x0001C8,
    /// The call's body uses a construct this build-time evaluation does not read.
    FoldCallNotEvaluable = 0x0001C9,

    // Defaults of ordinary parameters and ordinary arguments given by name (design principles
    //  4.4). 0x1CD and up, after the constant-folding codes. The `with`
    // parameter's forms are 0x1B7-0x1BE.
    /// A name in a call's argument list names no parameter of the callee.
    ParamArgumentUnknown = 0x0001CD,
    /// A parameter is given twice, once by position and once by name.
    ParamArgumentDuplicate = 0x0001CE,
    /// A call gives no value for a parameter that has no default.
    ParamArgumentMissing = 0x0001CF,
    /// An ordinary argument is given by name where the callee's signature is not known.
    ParamArgumentCallee = 0x0001D0,
    /// A name is given at a call of several declarations, and the parameter at the position the name
    /// means is not named the same way in every one of them (design principles 4.4): one named argument
    /// then means one parameter in one declaration and another in another, so no one parameter answers
    /// to the name. The rule is one rule for the two lists: a `with` argument is an argument here.
    OverloadParameterNames = 0x0001DF,
    /// A positional argument is written after a named one.
    ParamArgumentPositionalAfterNamed = 0x0001D1,
    /// The default of an ordinary parameter is not a compile-time constant.
    ParamDefaultNotConstant = 0x0001D2,
    /// The default of an ordinary parameter has a type that does not fit the parameter.
    ParamDefaultWrongType = 0x0001D3,
    /// An ordinary parameter without a default follows one that has a default.
    ParamAfterDefault = 0x0001D4,
    /// An argument at a call has a type the parameter it fills does not take.
    ParamArgumentWrongType = 0x0001D6,

    // Composition and the interval (`..`, design principles 4.2). 0x1D7 and up.
    /// Neither reading of `..` takes these operands: they are not two functions and not two integers.
    CompOperandMismatch = 0x0001E1,
    /// The left operand of `..` is a function that takes more or fewer than one parameter.
    CompOperandNotUnary = 0x0001E2,
    /// An operand of `..` is the name of a generic function, and nothing at this position says which instance it stands for. The refusal names the operand and both ways to settle it (design principles 5.5).
    CompOperandGenericWithoutType = 0x0001E4,
    /// The interval of two integers is written `a..b` and nothing else: the two-parameter `range(a, b)`
    /// the language used to have is gone (design principles 4.2).
    /// `range(a, b, 0)` is no sequence at all: the step never moves (design principles 4.2,
    /// which makes a step of 0 a fault and a constant one a compile-time error).
    RangeStepZero = 0x0001E6,
    /// A subscript slice with a constant step of 0 takes no element: `t[a:b:0]` (design principles 5.4;
    /// the step of a slice follows the same rule the step of a range does).
    SliceStepZero               = 0x0001E9,
    ReducedPrecisionUnsupported = 0x0001D7,
    // #impl(f) (design principles 10.4): the Camel body of the function is its semantics and the
    // body-less declaration f of the same module is the operator that runs it. The graph builder
    // resolves the tag when it declares the module, so no pass reads it and it names no reader.
    ImplOnBodylessDeclaration = 0x0001D8,
    ImplKernelUnknown         = 0x0001D9,
    ImplKernelForeign         = 0x0001DA,
    ImplSignatureMismatch     = 0x0001DB,
    ImplKernelNotBodyless     = 0x0001DC,
    // The node of a `const` parameter inside a rule's condition (rewrite design 2 (second version)
    //  1; the rule on `rule_when_const_node`): the surface name is `node_of(c)`,
    // it takes the name of one of the rule's own `const` parameters, and it is written in the
    // condition. Nothing else reaches a node there.
    // A stream is linear (design principles 5.4): it is read one element at a time and is finished
    // when it ends, so a container whose elements can be read more than once cannot hold one. The
    // rule (-stream-type-surface) names arrays, maps and sets; a tuple
    // is not a container in that sense - its items are taken apart once - and a function signature
    // may take and give a stream.
    StreamInContainer   = 0x0001E3,
    StreamConsumedTwice = 0x0001E5,
    NodeOfNotAParameter = 0x0001DE,
    // The element type of a value is in its type (design principles 5.1), so an array type writes one:
    // a shape with no element type in front of it asks a question the type of a value answers. A
    // signature that takes any element type declares a type variable in its head and writes it in the
    // element type's place.
    BranchElementTypeMismatch = 0x0001EE,
    RuleConstParamNotMatched  = 0x0001E8,
    RuleWithParameterUnbound  = 0x0001DD,
    /// The value bound to a rule's `with` parameter is part of what selects the instance its sides and
    // its condition are made at, so it is a value the compiler knows.
    RuleWithArgumentNotConstant = 0x0001F0,

    // The resource clause's promise (design effects plan 4.3, step 5): the resources a body infers
    // have to be within what its signature promises. The resource group above is 0x1A0-0x1A4, and
    // 0x1A5-0x1A6 are `std::cml` and 0x1A7 is empty, so this one is appended at the end of the
    // semantic space instead of being placed next to a group that has no room left.
    /// The resources a body uses are not within what its `pure`/`uses` signature promises.
    UsesPromiseViolated = 0x0001F1,
    // Where the rule itself can be said: 0x1F2 and up. Constructs that left the grammar are
    // ordinary syntax errors instead; these four are language rules, so each one names the rule
    // rather than saying "not supported".
    /// A type that mentions itself through a collection.
    TypeAliasRecursionUnrepresented = 0x0001F2,
    /// An `enum` written where a type is expected.
    EnumWrittenWhereATypeIsExpected = 0x0001F3,
    /// A struct comprehension that walks `indices`.
    StructComprehensionWithoutFields = 0x0001F4,
    /// An identifier pattern, or `error e`, over a type that is neither 'T?' nor 'T!'.
    IdentifierPatternNeedsNullableOrErrorType = 0x0001F5,

    // Warnings
    IgnoredSideEffect = 0x100002,
    EffectNotExecuted = 0x100004,
    // 0x90 and up, clear of what other work adds after EffectNotExecuted.
    ExitInUnusedBranch = 0x100090,
    // Design principles log 2.11: 0xC0 and up.
    UnusedFallibleValue = 0x1000C0,
    // Design principles log 2.13: 0x110 and up.
    NullTestNeverNull = 0x100110,
    KnownNotNull      = 0x100111,
    // Design principles log 2.13: the enum, 0x130 and up.
    EnumVariantCaseRepeated = 0x100130,
    MatchCaseAfterWildcard  = 0x100131,
    // `case _` after every variant is matched: the wildcard can never be taken.
    MatchWildcardRedundant = 0x100132,
    // Tags (design principles 6.2): the tag is declared for no pass in the pipeline, so nothing
    // reads what was written.
    TagHasNoReader = 0x100160,
    // A dimension name is written once in a signature, so it relates nothing (design principles
    // 5.4): write `?` if the size is not meant as a relation.
    DimensionNameUsedOnce = 0x100161,
    // Type variables (design principles 5.5). A head name written nowhere is a warning: the
    // declaration is still well formed, it just declares a parameter nothing can fill.
    /// A type parameter is declared at the head of a declaration and written nowhere in its
    /// signature, so no argument could ever give it a type.
    TypeVariableUnused = 0x1001A5,
};

constexpr DiagType diagTypeOf(SemanticDiag) { return DiagType::SemanticDiag; }

const std::unordered_map<SemanticDiag, DiagInfo> &getSemanticDiagInfoMap();

} // namespace camel::core::error
